class Solution {
    private int longestSpan(int[] bars){
        Arrays.sort(bars);
        int best=1,current=1;
        for(int i=1;i<bars.length;i++){
            if(bars[i]==bars[i-1]+1)current++;
            else current=1;
            best=Math.max(best,current);
        }
        return best+1;
    }
    public int maximizeSquareHoleArea(int n,int m,int[] hBars,int[] vBars){
        int side=Math.min(longestSpan(hBars),longestSpan(vBars));
        return side*side;
    }
}

code.kotlin:
class Solution {
    private fun longestSpan(bars:IntArray):Int{
        bars.sort();
        var best=1;
        var current=1;
        for(i in 1 until bars.size){
            current=if(bars[i]==bars[i-1]+1)current+1 else 1;
            best=maxOf(best,current)
        };
        return best+1
    }
    fun maximizeSquareHoleArea(n:Int,m:Int,hBars:IntArray,vBars:IntArray):Int{
        val side=minOf(longestSpan(hBars),longestSpan(vBars));
        return side*side
    }
}

